--
-- Name: handle_cierre_mes_cliente(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.handle_cierre_mes_cliente(p_cliente_id uuid, p_mes_ano text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_caller_role text;
  v_client record;
  v_task record;
  v_col record;
  v_initial_column_id uuid;
  v_next_mes_ano text;
  v_created integer := 0;
begin
  select role into v_caller_role from public.profiles where id = auth.uid();
  if v_caller_role is distinct from 'admin' then
    raise exception 'Sin permisos para ejecutar el cierre de mes';
  end if;

  if p_cliente_id is null then
    raise exception 'cliente_id es obligatorio';
  end if;
  if p_mes_ano is null or length(trim(p_mes_ano)) = 0 then
    raise exception 'mes_ano es obligatorio';
  end if;

  select * into v_client from public.clients where id = p_cliente_id;
  if not found then
    raise exception 'Cliente no encontrado';
  end if;

  v_next_mes_ano := to_char((to_date(p_mes_ano || '-01', 'YYYY-MM-DD') + interval '1 month'), 'YYYY-MM');

  -- 1. Congela el estado actual de las tareas del cliente correspondientes
  --    al mes que se está cerrando
  for v_task in
    select
      t.id, t.title, t.columna_matriz,
      d.name as dept_name,
      kc.title as col_title,
      cm.label as matriz_label
    from public.tasks t
    left join public.departments d on d.id = t.department_id
    left join public.kanban_columns kc on kc.id = t.column_id
    left join public.columnas_matriz cm on cm.value = t.columna_matriz
    where t.cliente_id = p_cliente_id
      and t.mes_tarea = p_mes_ano
  loop
      cliente_id, columna_matriz, columna_matriz_label, estado_final,
      departamento_final, mes_ano, task_id, task_title, created_by
    ) values (
      p_cliente_id, v_task.columna_matriz, v_task.matriz_label,
      coalesce(v_task.col_title, 'Sin estado'), v_task.dept_name,
      p_mes_ano, v_task.id, v_task.title, auth.uid()
    );
  end loop;

  -- 2. Elimina únicamente las tareas del mes cerrado (las de otros meses,
  --    como el mes siguiente ya preparado, no se tocan)
  delete from public.tasks where cliente_id = p_cliente_id and mes_tarea = p_mes_ano;

  -- 3. Crea automáticamente una tarea nueva por cada columna activa de la
  --    matriz, etiquetada con el mes siguiente
  for v_col in
    select * from public.columnas_matriz where is_active = true order by position asc
  loop
    v_initial_column_id := null;
    if v_col.department_id is not null then
      select id into v_initial_column_id
      from public.kanban_columns
      where department_id = v_col.department_id
      order by position asc
      limit 1;
    end if;

      title, cliente_id, periodo, columna_matriz, department_id, column_id,
      priority, approved, created_by, mes_tarea
    ) values (
      upper(v_col.label) || ' | ' || upper(v_client.brand_name),
      p_cliente_id, v_client.billing_period, v_col.value,
      v_col.department_id, v_initial_column_id,
      'normal', true, auth.uid(), v_next_mes_ano
    );

    v_created := v_created + 1;
  end loop;

  return v_created;
end;
$$;


ALTER FUNCTION public.handle_cierre_mes_cliente(p_cliente_id uuid, p_mes_ano text) OWNER TO postgres;

--
-- Name: handle_generar_proximo_mes_cliente(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.handle_generar_proximo_mes_cliente(p_cliente_id uuid, p_mes_actual text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_mes_nuevo text;
  v_col record;
  v_template record;
  v_creadas integer := 0;
  v_billing_period text;
begin
  -- Solo supervisores / admins pueden generar el próximo ciclo
  if not exists (
    select 1 from public.profiles
    where id = auth.uid()
      and (role = 'admin' or coalesce(is_super_admin, false) = true)
  ) then
    raise exception 'No autorizado para generar el próximo mes';
  end if;

  if p_cliente_id is null or p_mes_actual is null then
    raise exception 'Cliente o mes actual inválido';
  end if;

  -- Mes siguiente en formato YYYY-MM
  v_mes_nuevo := to_char(
    (to_date(p_mes_actual || '-01', 'YYYY-MM-DD') + interval '1 month'),
    'YYYY-MM'
  );

  select billing_period into v_billing_period
  from public.clients where id = p_cliente_id;

  for v_col in
    select * from public.columnas_matriz
    where is_active = true
    order by position
  loop
    -- Evitar duplicados: si ya existe tarea de ese entregable para el mes nuevo, se omite
    if not exists (
      select 1 from public.tasks
      where cliente_id = p_cliente_id
        and columna_matriz = v_col.value
        and mes_tarea = v_mes_nuevo
    ) then
      -- Plantilla: la tarea más reciente de ese entregable en el mes actual
      select * into v_template
      from public.tasks
      where cliente_id = p_cliente_id
        and columna_matriz = v_col.value
        and mes_tarea = p_mes_actual
      order by created_at desc
      limit 1;

        title, description, links,
        cliente_id, periodo, columna_matriz, mes_tarea,
        department_id, priority,
        column_id, approved, is_finished,
        allow_transfer, transfer_to_dept_ids,
        created_by
      ) values (
        coalesce(v_template.title, v_col.label),
        v_template.description,
        v_template.links,
        p_cliente_id,
        coalesce(v_template.periodo, v_billing_period),
        v_col.value,
        v_mes_nuevo,
        coalesce(v_template.department_id, v_col.department_id),
        coalesce(v_template.priority, 'normal'),
        null,   -- arranca "Por Distribuir": sin columna/estado asignado
        true,   -- generación de ciclo: no requiere aprobación manual
        false,  -- no finalizada
        coalesce(v_template.allow_transfer, false),
        v_template.transfer_to_dept_ids,
        coalesce(v_template.created_by, auth.uid())
      );

      v_creadas := v_creadas + 1;
    end if;
  end loop;

  return v_creadas;
end;
$$;


ALTER FUNCTION public.handle_generar_proximo_mes_cliente(p_cliente_id uuid, p_mes_actual text) OWNER TO postgres;

