--
-- Name: sync_schedule_on_task_handoff(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sync_schedule_on_task_handoff() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_owner_role text;
begin
  if new.column_id is not null
     and new.column_id is distinct from old.column_id
     and new.assigned_to is not null then

    select owner_role into v_owner_role
    from public.kanban_columns
    where id = new.column_id;

    if v_owner_role = 'admin' then
      update public.schedule_items si
      set done_by = case
            when not (new.assigned_to = any(coalesce(si.done_by, '{}'::uuid[])))
              then array_append(coalesce(si.done_by, '{}'::uuid[]), new.assigned_to)
            else si.done_by
          end
      where si.task_id = new.id
        and si.date = coalesce(new.fecha_cronograma, current_date);
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION public.sync_schedule_on_task_handoff() OWNER TO postgres;

--
-- Name: transfer_task(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.transfer_task(p_task_id uuid, p_dept_id uuid, p_column_id uuid, p_user_id uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_task record;
  v_caller_id uuid := auth.uid();
  v_caller_role text;
begin
  select * into v_task from public.tasks where id = p_task_id;

  if not found then
    raise exception 'Tarea no encontrada';
  end if;

  select role into v_caller_role from public.profiles where id = v_caller_id;

  if v_task.assigned_to <> v_caller_id
    and v_task.created_by <> v_caller_id
    and not (
      v_task.allow_transfer = true
      and v_task.department_id is not null
      and exists (
        select 1 from public.profile_departments
        where user_id = v_caller_id and department_id = v_task.department_id
      )
    )
    and not (
      v_caller_role = 'admin'
      and v_task.department_id is not null
      and exists (
        select 1 from public.profile_departments
        where user_id = v_caller_id and department_id = v_task.department_id and member_role = 'admin'
      )
    )
    -- Tareas "Por Distribuir" (sin departamento aun, ej. generadas por la
    -- Matriz de Control): cualquier admin/supervisor puede distribuirlas
    and not (
      v_caller_role = 'admin'
      and v_task.department_id is null
      and v_task.cliente_id is not null
    )
  then
    raise exception 'Sin permisos para transferir esta tarea';
  end if;

  if v_task.allow_transfer = false and v_caller_role <> 'admin' then
    raise exception 'Transferencia no habilitada para esta tarea';
  end if;

  update public.tasks
    set department_id = p_dept_id,
        column_id     = p_column_id,
        assigned_to   = coalesce(p_user_id, assigned_to),
        updated_at    = now()
    where id = p_task_id;
end;
$$;


ALTER FUNCTION public.transfer_task(p_task_id uuid, p_dept_id uuid, p_column_id uuid, p_user_id uuid) OWNER TO postgres;

