--
-- Name: task_messages; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.task_messages (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    task_id uuid NOT NULL,
    user_id uuid,
    content text,
    attachment_url text,
    attachment_type text,
    attachment_name text,
    created_at timestamp with time zone DEFAULT now(),
    edited_at timestamp with time zone,
    CONSTRAINT task_messages_attachment_type_check CHECK ((attachment_type = ANY (ARRAY['image'::text, 'video'::text, NULL::text])))
);

ALTER TABLE ONLY public.task_messages REPLICA IDENTITY FULL;


ALTER TABLE public.task_messages OWNER TO postgres;

--
-- Name: tasks; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.tasks (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    title text NOT NULL,
    description text,
    links text[],
    status text DEFAULT 'pending'::text NOT NULL,
    column_id uuid,
    department_id uuid,
    assigned_to uuid,
    created_by uuid,
    approved boolean,
    priority text DEFAULT 'normal'::text,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    allow_transfer boolean DEFAULT true,
    transfer_to_dept_ids uuid[] DEFAULT '{}'::uuid[],
    is_finished boolean DEFAULT false,
    cliente_id uuid,
    periodo text,
    columna_matriz text,
    mes_tarea text DEFAULT to_char(now(), 'YYYY-MM'::text) NOT NULL,
    fecha_cronograma date,
    CONSTRAINT tasks_mes_tarea_format_check CHECK ((mes_tarea ~ '^\d{4}-(0[1-9]|1[0-2])$'::text)),
    CONSTRAINT tasks_periodo_check CHECK ((periodo = ANY (ARRAY['1_31'::text, '15_14'::text]))),
    CONSTRAINT tasks_priority_check CHECK ((priority = ANY (ARRAY['low'::text, 'normal'::text, 'high'::text, 'urgent'::text]))),
    CONSTRAINT tasks_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'in_progress'::text, 'review'::text, 'done'::text])))
);


ALTER TABLE public.tasks OWNER TO postgres;

