--
-- Name: schedule_items Actualizar pendientes; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Actualizar pendientes" ON public.schedule_items FOR UPDATE TO authenticated USING (((( SELECT profiles.role
   FROM public.profiles
  WHERE (profiles.id = auth.uid())) = 'admin'::text) OR (auth.uid() = ANY (assigned_to))));


--
-- Name: clients Admin actualiza clientes; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Admin actualiza clientes" ON public.clients FOR UPDATE TO authenticated USING ((( SELECT profiles.role
   FROM public.profiles
  WHERE (profiles.id = auth.uid())) = 'admin'::text));


