-- Name: management_events Crear eventos de gestion; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Crear eventos de gestion" ON public.management_events FOR INSERT TO authenticated WITH CHECK (((created_by = auth.uid()) AND (EXISTS ( SELECT 1
   FROM public.profiles p
  WHERE ((p.id = auth.uid()) AND ((p.role = 'admin'::text) OR (p.is_super_admin = true))))) AND (array_length(assigned_to_ids, 1) > 0) AND (NOT (EXISTS ( SELECT 1
   FROM unnest(management_events.assigned_to_ids) uid(uid)
  WHERE (NOT (EXISTS ( SELECT 1
           FROM public.profiles pt
          WHERE ((pt.id = uid.uid) AND ((pt.role = 'admin'::text) OR (pt.is_super_admin = true))))))))) AND ((assigned_to_ids = ARRAY[auth.uid()]) OR (EXISTS ( SELECT 1
   FROM public.profiles p
  WHERE ((p.id = auth.uid()) AND (p.is_super_admin = true)))))));


