   FROM unnest(management_events.assigned_to_ids) uid(uid)
  WHERE (NOT (EXISTS ( SELECT 1
           FROM public.profiles pt
          WHERE ((pt.id = uid.uid) AND ((pt.role = 'admin'::text) OR (pt.is_super_admin = true))))))))) AND ((assigned_to_ids = ARRAY[auth.uid()]) OR (EXISTS ( SELECT 1
   FROM public.profiles p
  WHERE ((p.id = auth.uid()) AND (p.is_super_admin = true)))))));


