--
-- Name: tasks tasks_delete; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY tasks_delete ON public.tasks FOR DELETE TO authenticated USING (((( SELECT profiles.role
   FROM public.profiles
  WHERE (profiles.id = auth.uid())) = 'admin'::text) AND (department_id IN ( SELECT profile_departments.department_id
   FROM public.profile_departments
  WHERE ((profile_departments.user_id = auth.uid()) AND (profile_departments.member_role = 'admin'::text))))));


--
-- Name: tasks tasks_insert; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY tasks_insert ON public.tasks FOR INSERT TO authenticated WITH CHECK ((created_by = auth.uid()));


--
-- Name: tasks tasks_select; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY tasks_select ON public.tasks FOR SELECT TO authenticated USING (((department_id IN ( SELECT profile_departments.department_id
   FROM public.profile_departments
  WHERE (profile_departments.user_id = auth.uid()))) OR (assigned_to = auth.uid()) OR (created_by = auth.uid())));


--
-- Name: tasks tasks_update; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY tasks_update ON public.tasks FOR UPDATE TO authenticated USING (((assigned_to = auth.uid()) OR (created_by = auth.uid()) OR ((allow_transfer = true) AND (department_id IN ( SELECT profile_departments.department_id
   FROM public.profile_departments
  WHERE (profile_departments.user_id = auth.uid())))) OR ((( SELECT profiles.role
   FROM public.profiles
  WHERE (profiles.id = auth.uid())) = 'admin'::text) AND (department_id IN ( SELECT profile_departments.department_id
   FROM public.profile_departments
  WHERE ((profile_departments.user_id = auth.uid()) AND (profile_departments.member_role = 'admin'::text))))))) WITH CHECK (true);


